  tests: [
    { id: 54204, type: 'fill-blank', instruction: "Bo'sh joyni to'ldiring:", question: "Subjunctive present = _______ verb (no -s).", blanks: ['base'], acceptedAnswers: [['base']], explanation: 'Subjunctive = base verb (no -s)' },
    { id: 54205, type: 'error-correction', instruction: "Xatoni toping va to'g'rilang:", question: "I suggest that he goes now.", errorPart: 'goes', correct: 'go', explanation: 'Suggest + that + base verb = subjunctive. Qoida: I suggest that he GO (not goes) now. (U hozir ketsin.) \'That\' + S + V1 (-s qo\'shimchasisiz!)' },
    { id: 54206, type: 'transformation', instruction: "Ma'nosi bilan bog'lang:", question: "Were-subjunctive qanday vaziyatda ishlatiladi?", hint: "_____ (haqiqiy yoki xayoliy?)", correct: 'xayoliy vaziyat', explanation: 'Were = unreal = haqiqiy bo\'lmagan vaziyatlar \'were\'. Qoida: Shart maylida barcha shaxslar bilan \'were\' ishlatiladi: If I were you... (Agar men sening o\'rningda bo\'lsam...) I wish I were taller. (Qaniydi baland bo\'lsam edi.)' },
    { id: 54207, type: 'fill-blank', instruction: "Bo'sh joyni to'ldiring:", question: "If I ___ you, I would go.", blanks: ['were'], acceptedAnswers: [['were']], explanation: 'If I were you (subjunctive) = maslahat. Qoida: Eng keng tarqalgan shart mayli iborasi: If I were you, I\'d accept the offer. (Men sening o\'rningda bo\'lsam, taklifni qabul qilardim.) Doim \'were\', \'was\' emas.' },
    { id: 54208, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Subjunctive qaysi registrda ishlatiladi?", blanks: ["rasmiy/written"], explanation: "Subjunctive = formal/written = rasmiy/yozma uslub. Qoida: Subjunctive asosan rasmiy yozuvda: It is essential that every student submit the form. (Har bir talaba formani topshirishi SHART.)" },
    { id: 54209, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "I suggest that he ___ now.", blanks: ["go"], explanation: "Base verb = fe'lning asosiy shakli (V1). Subjunctive'da suggest that he study -- studies emas." },
    { id: 54210, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "It's essential that she ___ present.", blanks: ["be"], explanation: "Subjunctive: 'If I were' (was emas!). 'If I were rich, I would travel.'" },
    { id: 54211, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "They insisted that he ___ invited.", blanks: ["be"], explanation: "Passive subjunctive → be + V3 = majhul subjunctive. Qoida: It was suggested that the meeting BE POSTPONED. (Yig'ilishni kechiktirish taklif qilindi.) 'Be + V3' passive subjunctive." },
    { id: 54212, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "He acts as if he ___ the boss.", blanks: ["were"], explanation: "As if + were = go'yo (haqiqiy emas). Qoida: 'As if' + were (barcha shaxslar): He acts as if he were the boss. (U go'yo xo'jayindek harakat qiladi.) Haqiqiy emas shart mayli." },
    { id: 54213, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "The law requires that all citizens ___ taxes.", blanks: ["pay"], explanation: "Base verb after require that = 'require + that + V1'. Qoida: Subjunctive after 'require that': The law requires that every driver have insurance. (Qonun har bir haydovchining sug'urtasi bo'lishini talab qiladi.)" },
    { id: 54214, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Qaysi gapda subjunctive NOTO'G'RI?", options: ["I'm happy he comes", "I insist that he come", "I demand that he be present", "It's essential that she go"], correct: "I'm happy he comes", explanation: "I'm happy he comes = indicative (haqiqiy), subjunctive emas" },
    { id: 54215, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "BrE va AmE farqi: qaysi biri subjunctive ko'proq?", blanks: ["American English"], explanation: "AmE subjunctive ko'proq ishlatadi" },
    { id: 54216, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "'If I was late' vs 'If I were late' farqi?", blanks: ["was = haqiqiy, were = xayoliy"], explanation: "Was = real possibility. Were = unreal." },
    { id: 54217, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "Qaysi gap TO'G'RI?", options: ["I demand that he be released", "I demand that he is released", "I demand that he being released", "I demand that he to be released"], correct: "I demand that he be released", explanation: "Subjunctive → be (to'g'ri)" },
    { id: 54218, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "'Suffice it to say' qanday subjunctive?", blanks: ["fixed expression"], explanation: "Suffice it to say = fixed subjunctive expression" },
    { id: 54219, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Passive subjunctive: 'They demand that the report ___ by Friday.'", blanks: ["be submitted"], explanation: "Passive subjunctive → be + V3 (be submitted)" },
    { id: 54220, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "Qaysi gap RASMIY English da to'g'ri?", blanks: ["I suggest that he go"], explanation: "Formal subjunctive: suggest + that + base verb (no -s)" },
    { id: 54221, type: 'fill-blank', instruction: "To'g'ri javobni yozing:", question: "'Were I to accept this position...' — bu qanday tuzilma?", blanks: ["inverted conditional subjunctive"], explanation: "Were + S + to V = inverted conditional with subjunctive (formal)" },
  ],
